const buildQuestions = (moduleId, rows) =>
  rows.map(([difficulty, category, prompt, correctAnswer, wrongAnswers, explanation, learning = {}], index) => ({
    id: `${moduleId}-extra-${index + 1}`,
    type: 'mcq',
    difficulty,
    category,
    prompt,
    options: [correctAnswer, ...wrongAnswers],
    correctAnswer,
    explanation,
    ...learning,
  }))

